INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3f949d621513ec37a229','AMEDEX 2025 Ethics file 1.pdf','30','Ethics/Population Health','You are counseling a 42-year-old patient who
was diagnosed with HIV infection last month.
He has been in a stable relationship with his
girlfriend for the past eight months. He has had
three visits to your office for consultation
regarding referral, antiretroviral therapy, and
further investigations for other sexually
transmissible infections (STIs). He has no STI
other than HIV. In the past visits, you talked
about the importance of contact tracing. You
told him that he should speak to her girlfriend
about his disease and brings her in for HIV
testing but every time he adamantly insists that
it is his secret and he does not want anyone to
know about it, her in particular. During this visit,
her girlfriend accompanies him and sits in the
waiting room. You again emphasize that he
should inform her; otherwise, her health is at
more risk. He again refuses to tell her. Which
one of the following is the most appropriate
action you should take?','{"A":"Respect the patient''s wishes.","B":"Obtain a court order to inform his partner.","C":"Consult with the ethics committee.","D":"Personally notify her or notify the health department.","E":"Advise safe sex."}','C',NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","supporting_pages":[30,32],"source_qid":null,"duplicate_group_id":"exact-5c1ebfb52d2b","duplicate_sources":[{"record_id":"3f949d621513ec37a229","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":30,"source_qid":null},{"record_id":"42abdfcbae12d06faf81","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":454,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"3f949d621513ec37a229","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_year":2025,"source_page":30,"supporting_pages":[30,32],"source_qid":null,"domain_hint":"Ethics/Population Health","stem":"You are counseling a 42-year-old patient who\nwas diagnosed with HIV infection last month.\nHe has been in a stable relationship with his\ngirlfriend for the past eight months. He has had\nthree visits to your office for consultation\nregarding referral, antiretroviral therapy, and\nfurther investigations for other sexually\ntransmissible infections (STIs). He has no STI\nother than HIV. In the past visits, you talked\nabout the importance of contact tracing. You\ntold him that he should speak to her girlfriend\nabout his disease and brings her in for HIV\ntesting but every time he adamantly ins