INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ba641e263fa004855362','AMEDEX 2025 Ethics file 1.pdf','48','Ethics/Population Health','Non-sexual transmission can also occur trom direc
contact with caretakers contaminated with genital
HPV or common warts. For example, caretakers
with genital warts who touch or scratch their
genitals and then, without washing their hands,
change a baby''s diaper or assist a child with
toileting/bathing may transmit the virus to the
child''s genitals. HPV transmission via contact with
contaminated objects or surfaces is also possible.
The mother has been treated with CIN1. Although
HPV serotypes associated with cervical cancer are
different from those causing anogenital warts, the
presence of cervical neoplasia could suggest co-
infections with other types of HPV as well. In this
child, with the mother’s possible infection and the
child’s age, the most likely cause of the child''s
anogenital warts appears to be a perinatal infection
from the mother.
lf the child was older the likelihood of sexual abuse
would be more pronounced, as perinatal infection
must have presented by 2 years of age, as most
authors believe. Although not a rule, the younger
the child, the more likely the HPV infections are
due to perinatal infections rather than sexual
abuse.
Reference(s) »° edscape - Ano-Genital Warts in
Children: Sexual Abuse or Not?
¢ NCBI - Genital warts in children:
what do they mean?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","supporting_pages":[48],"source_qid":null,"duplicate_group_id":"exact-730d47fcbddd","duplicate_sources":[{"record_id":"ba641e263fa004855362","record_type":"visual_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":48,"source_qid":null}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/AMEDEX_2025_Ethics_file_1__6e3896950081/page_00048.jpg","asset_preview_url":"https://drive.google.com/file/d/1gRzIF7qr5RT7cIqyYnsd11uU8vG-bG5A/preview"}','visual_assets/AMEDEX_2025_Ethics_file_1__6e3896950081/page_00048.jpg','https://drive.google.com/thumbnail?id=1gRzIF7qr5RT7cIqyYnsd11uU8vG-bG5A&sz=w1600','source_page_image',NULL,'needs_verification','[]','medium','{"record_id":"ba641e263fa004855362","record_type":"visual_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_year":2025,"source_page":48,"supporting_pages":[48],"source_qid":null,"domain_hint":"Ethics/Population Health","stem":"Non-sexual transmission can also occur trom direc\ncontact with caretakers contaminated with genital\nHPV or common warts. For example, caretakers\nwith genital warts who touch or scratch their\ngenitals and then, without washing their hands,\nchange a baby''s diaper or assist a child with\ntoileting/bathing may transmit the virus to the\nchild''s genitals. HPV transmission via contact with\ncontaminated objects or surfaces is also possible.\nThe mother has been treated with CIN1. Although\nHPV serotypes associated with cervical cancer are\ndifferent from those causing anogenital warts, the\npresence of cervical neoplasia could suggest co-\ninfections with other types of HPV as well. In this\nchild, with the mother’s possible infection and the\nchild’s age, the most likely cause of the child''s\nanogenital warts appears to be a perinatal infection\nfrom the mother.\nlf the child was older the likelihood of sexual abuse\nwould be more pronounced, as perinatal infection\nmust have presented by 2 years of age, as most\nauthors believe. Although not a rule, the younger\nthe child, the more likely the HPV infections are\ndue to perinatal infections rather than sexual\nabuse.\nReference(s) »° edscape - Ano-Genital Warts in\nChildren: Sexual Abuse or Not?\n¢ NCBI - Genital warts in children:\nwhat do they mean?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/AMEDEX_2025_Ethics_file_1__6e3896950081/page_00048.jpg","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v28_visual_page_asset","text_method":"source_page_image+best_available_text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"730d47fcbddd540ef0ca728bc1f671adf4f906d8","duplicate_group_id":"exact-730d47fcbddd","duplicate_sources":[{"record_id":"ba641e263fa004855362","record_type":"visual_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":48,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.