INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('06dd0535b38ac8ab5759','AMEDEX 2025 Ethics file 1.pdf','58','Ethics/Population Health','Assane, /8 years old, is admitted to the hospital
due to flu. He has advanced Alzheimer’s
disease and is no longer able to eat, drink, or
communicate independently. A court of law has
appointed her daughter, Fatima, his legal
guardian. The treating doctor recommends
artificial nutrition and hydration for Assane. At
the same time, his daughter is unsure whether
this decision is aligned with her father’s
expressed wishes and best interests and
advises against this proposed treatment. Which
of the following is the best action in this
scenario?','{"A":"Withhold the treatment; instead,\nconcentrate on providing comfort for\nAssane.","B":"Respect Fatima’s decision as\nAssane''s legal guardian.","C":"Proceed with initiating artificial\nnutrition and hydration (ANH) based\non the healthcare team''s\nrecommendation.","D":"Consult with the ethics committee.","E":"Convince Fatima that her decision is\nagainst her father''s best interest."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","supporting_pages":[58,59],"source_qid":null,"duplicate_group_id":"exact-c0c2857fd292","duplicate_sources":[{"record_id":"06dd0535b38ac8ab5759","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":58,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"06dd0535b38ac8ab5759","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_year":2025,"source_page":58,"supporting_pages":[58,59],"source_qid":null,"domain_hint":"Ethics/Population Health","stem":"Assane, /8 years old, is admitted to the hospital\ndue to flu. He has advanced Alzheimer’s\ndisease and is no longer able to eat, drink, or\ncommunicate independently. A court of law has\nappointed her daughter, Fatima, his legal\nguardian. The treating doctor recommends\nartificial nutrition and hydration for Assane. At\nthe same time, his daughter is unsure whether\nthis decision is aligned with her father’s\nexpressed wishes and best interests and\nadvises against this proposed treatment. Which\nof the following is the best action in this\nscenario?","options":{"A":"Withhold the treatment; instead,\nconcentrate on providing co