INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2992f8f25da0a26bc595','AMEDEX 2025 Ethics file 1.pdf','105','Ethics/Population Health','A 32-year-old woman presents to your GP
practice with complaints of disturbed sleep,
colicky abdominal pain, and headaches. During
the examination, you notice several bruises
over her arms, legs, and chest. Upon further
inquiry, she confides in you that she has been
beaten by her husband and this happens almost
