INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('60f306c1445a7f125067','AMEDEX 2025 Ethics file 1.pdf','126','Ethics/Population Health','David, 7 years old, had a preliminary diagnosis
of acute lymphoblastic leukemia (ALL), for
which he was referred to an oncologist. The
oncology team has decided to start him on
chemotherapy, and it is believed that without
treatment, David’s condition will deteriorate
progressively and will have less chance of
survival. David''s parents hold a strong belief
that chemotherapy is toxic and will not benefit
David. Instead, they believe in the healing
power of faith and prayer, and they insist that
they treat him in their own way, with measures
such as cleansing diet and energy healing.
Explaining the importance of prompt treatment
for David as soon as possible fails to convince
them otherwise. Which of the following will be
the most appropriate course of action in this
situation?','{"A":"Ignore the parents’ wishes and\nbeliefs and proceed to the\nchemotherapy in David''s best\ninterest.","B":"Follow their wishes, as they are\nDavid''s decision-makers, and no one\ncan force them to act against their\nbeliefs.","C":"seek an urgent court hearing for\ndecision-making regarding the\ntreatment.","D":"Refer the case to the child protection\nservices as this is a case of\nnegligence.","E":"Ask for the advice of an Ethics\nCommittee to resolve the conflict\nbetween the parents’ decision and\nDavid''s best interest."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","supporting_pages":[126,128],"source_qid":null,"duplicate_group_id":"exact-525e7e7d4ff0","duplicate_sources":[{"record_id":"60f306c1445a7f125067","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":126,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"60f306c1445a7f125067","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_year":2025,"source_page":126,"supporting_pages":[126,128],"source_qid":null,"domain_hint":"Ethics/Population Health","stem":"David, 7 years old, had a preliminary diagnosis\nof acute lymphoblastic leukemia (ALL), for\nwhich he was referred to an oncologist. The\noncology team has decided to start him on\nchemotherapy, and it is believed that without\ntreatment, David’s condition will deteriorate\nprogressively and will have less chance of\nsurvival. David''s parents hold a strong belief\nthat chemotherapy is toxic and will not benefit\nDavid. Instead, they believe in the healing\npower of faith and prayer, and they insist that\nthey treat him in their own way, with measures\nsuch as cleansing diet and energy healing.\nExplaining the importance of prompt treatment\nfor David as soon as possible fails to convince\nthem otherwise. Which of the following will be\nthe most appropriate course of action in this\nsituation?","options":{"A":"Ignore the parents’ wishes and\nbeliefs and proceed to the\nchemotherapy in David''s best\ninterest.","B":"Follow their wishes, as they are\nDavid''s decision-makers, and no one\ncan force them to act against their\nbeliefs.","C":"seek an urgent court hearing for\ndecision-making regarding the\ntreatment.","D":"Refer the case to the child protection\nservices as this is a case of\nnegligence.","E":"Ask for the advice of an Ethics\nCommittee to resolve the conflict\nbetween the parents’ decision and\nDavid''s best interest."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["therapy","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"525e7e7d4ff086bb4e8ebf2f8f9439108f69c020","duplicate_group_id":"exact-525e7e7d4ff0","duplicate_sources":[{"record_id":"60f306c1445a7f125067","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":126,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded