INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1103aeb026380994c26d','AMEDEX 2025 Ethics file 1.pdf','144','Ethics/Population Health','You are a medical officer in a tertiary hospital.
A patient is about to undergo abdominal
surgery. When the patient is being
transferred to the operating theatre, the
nurse informs you that consent for the
Surgery has not yet been obtained. Which
one of the following is the most appropriate
