INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('08fae945450218fbf345','AMEDEX 2025 Ethics file 3.pdf','14','Ethics/Population Health','Sue, an 18-year-old girl, presents to your
clinic with lower abdominal pain and fishy-
smelling vaginal discharge for the past three
days. You are a male doctor and a female
nurse is on duty at the clinic. You mention to
the patient that she needs a vaginal
examination, but she declines to be
examined by you and says that she wants a
female doctor to examine her. Which one of
the following is the most appropriate action
in this situation?','{"A":"Call her boyfriend to be present\nwhile you are examining her.","B":"Treat the patient without vaginal\nexamination.","C":"Convince the patient that female\nchaperon will be present during the\nexamination.","D":"Defer the examination and inform\nthe patient about the associated\nrisks of not doing the examination.","E":"Ask the nurse to perform the\nvaginal examination."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 3.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-0c16178ea3ac","duplicate_sources":[{"record_id":"08fae945450218fbf345","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 3.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 3.pdf","source_page":14,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"08fae945450218fbf345","source_file":"AMEDEX 2025 Ethics file 3.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 3.pdf","source_year":2025,"source_page":14,"source_qid":null,"domain_hint":"Ethics/Population Health","stem":"Sue, an 18-year-old girl, presents to your\nclinic with lower abdominal pain and fishy-\nsmelling vaginal discharge for the past three\ndays. You are a male doctor and a female\nnurse is on duty at the clinic. You mention to\nthe patient that she needs a vaginal\nexamination, but she declines to be\nexamined by you and says that she wants a\nfemale doctor to examine her. Which one of\nthe following is the most appropriate action\nin this situation?","options":{"A":"Call her boyfriend to be present\nwhile you are examining her.","B":"Treat the patient without vaginal\nexamination.","C":"Convince the patient that female\nchaperon will be present during the\nexamination.","D":"Defer the examination and inform\nthe patient about the associated\nrisks of not doing the examination.","E":"Ask the nurse to perform the\nvaginal examination."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0c16178ea3aca42c0da54089f145cfdfcbb8463a","duplicate_group_id":"exact-0c16178ea3ac","duplicate_sources":[{"record_id":"08fae945450218fbf345","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 3.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 3.pdf","source_page":14,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
